def xs(c):
    return 130 + 50 * (c - 1)


def fig(fid, title, rows, ncyc):
    o = []
    o.append('<svg viewBox="0 0 640 %d" role="img" aria-labelledby="%s-t"><title id="%s-t">%s</title>' % (40 + 34 * len(rows), fid, fid, title))
    o.append('<g font-family="system-ui, sans-serif" font-size="16" text-anchor="middle" fill="currentColor">')
    o.append('<text x="60" y="20" style="fill: var(--muted)">cycle</text>')
    for c in range(1, ncyc + 1):
        o.append('<text x="%d" y="20" style="fill: var(--muted)">%d</text>' % (xs(c) + 23, c))
    for r, (name, cells) in enumerate(rows):
        y = 32 + 34 * r
        o.append('<text x="8" y="%d" text-anchor="start">%s</text>' % (y + 20, name))
        for c in sorted(cells):
            t, k = cells[c]
            cls = {'n': 'c', 'w': 'c w', 'a': 'c a'}[k]
            o.append('<rect class="%s" x="%d" y="%d" width="46" height="28" rx="4"/><text x="%d" y="%d">%s</text>' % (cls, xs(c), y, xs(c) + 23, y + 20, t))
    o.append('</g></svg>')
    return '\n'.join(o)


def std(start, special=None):
    d = {}
    for i, s in enumerate(['IF', 'ID', 'EX', 'MEM', 'WB']):
        d[start + i] = (s, 'n')
    if special:
        d.update(special)
    return d


f1 = fig('fig1', 'Structural hazard: the fourth instruction cannot be fetched in cycle 4 because the load is using memory', [
    ('lw r1,0(r2)', std(1, {4: ('MEM', 'a')})),
    ('add r3,r4,r5', std(2)),
    ('sub r6,r7,r8', std(3)),
    ('or r9,r10,r11', std(5, {4: ('–', 'w')})),
], 9)
f2 = fig('fig2', 'Data hazard: sub waits two cycles in ID for the value that add writes in cycle 5', [
    ('add r1,r2,r3', std(1, {5: ('WB', 'a')})),
    ('sub r4,r1,r5', {2: ('IF', 'n'), 3: ('ID', 'w'), 4: ('ID', 'w'), 5: ('ID', 'a'), 6: ('EX', 'n'), 7: ('MEM', 'n'), 8: ('WB', 'n')}),
], 8)
f3 = fig('fig3', 'Control hazard: two instructions fetched after the branch are thrown away, and the real next instruction is fetched in cycle 4', [
    ('beq r1,r2,T', std(1, {3: ('EX', 'a')})),
    ('wrong path 1', {2: ('IF', 'w'), 3: ('ID', 'w')}),
    ('wrong path 2', {3: ('IF', 'w')}),
    ('target T', std(4)),
], 8)
